import {useCallback,useEffect,useMemo,useRef,useState, type FormEvent, type ReactNode} from 'react'
import {Area,AreaChart,CartesianGrid,Line,LineChart,ResponsiveContainer,Tooltip,XAxis,YAxis} from 'recharts'
import {Activity,ArrowLeft,ArrowRight,ArrowUpRight,Bell,BrainCircuit,Check,CheckCircle2,ChevronRight,CircleAlert,Clock3,Database,Droplets,Filter,Gauge,Info,Leaf,LockKeyhole,LogOut,MapPin,MessageCircle,Plus,RefreshCw,Search,Send,ScanLine,Settings2,Shield,ShieldCheck,SlidersHorizontal,Sparkles,Sun,Moon,Wifi,TreePine,TrendingUp,UserRound,Waves,Wrench,X,Zap, type LucideIcon} from 'lucide-react'
import AuthScreen from './AuthScreen'
import DeviceMedia from './DeviceMedia'
import DeviceThumbnail from './DeviceThumbnail'
import SolarTreeMark from './SolarTreeMark'
import PhonePairing from './PhonePairing'
import ConnectionGuide from './ConnectionGuide'
import ResourcePlanner from './ResourcePlanner'
import PairQrScanner from './PairQrScanner'
import {api,setAuthToken} from './api'
import type {Alert,ChatMessage,Forecast,Health,Page,Reading,Service,TokenPayload,Tree,User,OxygenHistory,PairResult} from './types'
import './styles.css'

const formatNum=(n:number,d=0)=>new Intl.NumberFormat('bg-BG',{maximumFractionDigits:d,minimumFractionDigits:d}).format(n)
const formatWhen=(iso:string)=>new Date(iso).toLocaleDateString('bg-BG',{day:'2-digit',month:'short',year:'numeric'})
const formatTime=(iso:string)=>new Date(iso).toLocaleTimeString('bg-BG',{hour:'2-digit',minute:'2-digit'})
const relativeDay=(s:Service)=>s.status==='overdue'?`${Math.abs(s.days_left)} дни просрочено`:s.days_left===0?'Днес':`След ${s.days_left} дни`
function serviceColor(status:Service['status']){return status==='overdue'?'danger':status==='soon'?'amber':'good'}
function initial(name:string){return name.trim().slice(0,1).toUpperCase()||'S'}
function Logo({small=false}:{small?:boolean}){return <div className={`brand ${small?'brand-small':''}`}><div className="brand-symbol"><Leaf size={24} strokeWidth={2.5}/><span/></div>{!small&&<div className="brand-copy"><strong>SolarTree<span> AI</span></strong><small>INTELLIGENT ECOSYSTEM</small></div>}</div>}
function IconButton({icon:Icon,title,onClick,badge,active=false}:{icon:LucideIcon;title:string;onClick:()=>void;badge?:boolean;active?:boolean}){return <button className={`icon-btn ${active?'active':''}`} type="button" aria-label={title} title={title} onClick={onClick}><Icon size={19}/>{badge&&<i className="mini-dot"/>}</button>}
function StatePill({tree}:{tree:Tree}){const live=tree.connection==='live';return <span className={`state-pill ${live?'live':tree.connection==='model'?'virtual':'offline'}`}><i/>{live?'Свързано':tree.connection==='model'?'Симулация':'Няма връзка'}</span>}
function SectionHeading({eyebrow,title,action}:{eyebrow?:string;title:string;action?:ReactNode}){return <div className="section-heading"><div>{eyebrow&&<span className="eyebrow">{eyebrow}</span>}<h2>{title}</h2></div>{action}</div>}
function Panel({children,className='' }:{children:ReactNode;className?:string}){return <div className={`panel ${className}`}>{children}</div>}
function Empty({icon:Icon=TreePine,title,desc,action}:{icon?:LucideIcon;title:string;desc:string;action?:ReactNode}){return <div className="empty-state"><div className="empty-icon"><Icon size={26}/></div><h3>{title}</h3><p>{desc}</p>{action}</div>}
function ErrorText({message}:{message:string}){return <div className="error-note"><CircleAlert size={16}/>{message}</div>}
function TelemetryChart({readings,small=false}:{readings:Reading[];small?:boolean}){
  const currentSource=readings.at(-1)?.source
  const rows=useMemo(()=>readings.filter(r=>r.source===currentSource).map(r=>({at:formatTime(r.time),w:r.power_w,time:r.time})).slice(-Math.max(24,small?48:100)),[readings,small,currentSource])
  if(!rows.length)return <Empty icon={Activity} title="Няма измервания" desc="Показателите ще се появят след свързване на устройството или въвеждане на сценарий."/>
  return <div className={`chart-box ${small?'chart-small':''}`}><span className="chart-source-badge">{currentSource==='device'?'Измерени данни':'Симулация'}</span><ResponsiveContainer width="100%" height="100%"><AreaChart data={rows} margin={{top:14,right:6,left:-24,bottom:0}}><defs><linearGradient id="powerGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#bdf98a" stopOpacity={.25}/><stop offset="96%" stopColor="#bdf98a" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#273236" vertical={false} strokeDasharray="3 6"/><XAxis dataKey="at" stroke="#627477" tick={{fill:'#758687',fontSize:11}} tickLine={false} axisLine={false} minTickGap={38}/><YAxis stroke="#627477" tick={{fill:'#758687',fontSize:11}} tickLine={false} axisLine={false} tickFormatter={v=>`${v}`}/><Tooltip contentStyle={{background:'#1b2628',border:'1px solid #34413f',borderRadius:12,color:'#eaf5eb',fontSize:12}} labelStyle={{color:'#a7b6af'}} formatter={(value)=>[`${formatNum(Number(value))} W`,'Мощност']}/><Area type="monotone" dataKey="w" stroke="#c4f891" strokeWidth={2.4} fill="url(#powerGradient)" dot={false} activeDot={{r:4,stroke:'#c4f891',fill:'#23352c'}}/></AreaChart></ResponsiveContainer></div>
}
function OxygenChart({history}:{history:OxygenHistory|null}){
  const rows=history?.points||[]
  if(!rows.length)return <Empty icon={Waves} title="Все още няма данни за кислород" desc="Свържи датчик за кислороден дебит или зареди данни от симулацията."/>
  return <div className="oxygen-chart-wrap"><div className="oxygen-highlights"><div><small>За периода</small><strong>{formatNum(history?.total_l||0,1)} <span>L O₂</span></strong></div><div><small>Последен дебит</small><strong>{formatNum(history?.current_flow_lph||0,1)} <span>L/h</span></strong></div><span className="oxygen-source">{history?.basis==='measured'?'От датчик':history?.basis==='simulation'?'Симулирани стойности':history?.basis==='estimated'?'Изчислени стойности':'Няма източник'}</span></div><div className="chart-box"><ResponsiveContainer width="100%" height="100%"><AreaChart data={rows.map(r=>({at:formatTime(r.time),liters:r.cumulative_l}))} margin={{top:14,right:9,left:-18,bottom:0}}><defs><linearGradient id="oxygenGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#78d6e9" stopOpacity={.28}/><stop offset="95%" stopColor="#78d6e9" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#273236" vertical={false} strokeDasharray="3 6"/><XAxis dataKey="at" tick={{fill:'#758687',fontSize:11}} minTickGap={35} tickLine={false} axisLine={false}/><YAxis tick={{fill:'#758687',fontSize:11}} tickLine={false} axisLine={false}/><Tooltip contentStyle={{background:'#1b2628',border:'1px solid #34413f',borderRadius:12,color:'#eaf5eb'}} formatter={v=>[`${formatNum(Number(v),1)} L`,'Натрупан кислород']}/><Area type="monotone" dataKey="liters" stroke="#78d6e9" strokeWidth={2.5} dot={false} fill="url(#oxygenGradient)"/></AreaChart></ResponsiveContainer></div></div>
}
function ForecastChart({forecast}:{forecast:Forecast|null}){
  if(!forecast||!forecast.points?.length)return <Empty icon={TrendingUp} title="Все още няма прогноза" desc="Необходими са повече записи от избраното дърво."/>
  return <div className="chart-box"><ResponsiveContainer width="100%" height="100%"><LineChart data={forecast.points.map(x=>({at:formatTime(x.time),w:x.power_w}))} margin={{top:18,right:10,left:-23,bottom:0}}><CartesianGrid stroke="#273236" vertical={false} strokeDasharray="3 6"/><XAxis dataKey="at" stroke="#758687" tick={{fill:'#758687',fontSize:11}} tickLine={false} axisLine={false}/><YAxis tick={{fill:'#758687',fontSize:11}} tickLine={false} axisLine={false} stroke="#758687"/><Tooltip contentStyle={{background:'#1b2628',border:'1px solid #34413f',borderRadius:12,color:'#eaf5eb'}} formatter={v=>[`${formatNum(Number(v))} W`,'Прогноза']}/><Line dataKey="w" type="monotone" stroke="#c4f891" strokeWidth={3} dot={{fill:'#c4f891',r:4}} activeDot={{r:5}}/></LineChart></ResponsiveContainer></div>
}
function NewTreeModal({onClose,onSave,onPhoneAdded}:{onClose:()=>void;onSave:(value:{name:string;code:string;claim_token:string;location:string;lat:number|null;lng:number|null})=>Promise<void>;onPhoneAdded:(treeId:number)=>Promise<void>}){
  const [name,setName]=useState(''),[code,setCode]=useState(''),[token,setToken]=useState(''),[location,setLocation]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[resolved,setResolved]=useState<PairResult|null>(null)
  async function resolve(c=code,t=token){setBusy(true);setError('');setResolved(null);try{const r=await api.pairResolve(c,t);setCode(r.code);setToken(t);setResolved(r)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{if(!resolved)throw new Error('Първо разпознай устройството.');await onSave({name,code:resolved.code,claim_token:token,location,lat:null,lng:null})}catch(err){setError((err as Error).message)}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal pairing-modal"><div className="modal-heading"><div><span className="eyebrow">СВЪРЗВАНЕ НА УСТРОЙСТВО</span><h2>Добавяне на дърво</h2></div><IconButton title="Затвори" icon={X} onClick={onClose}/></div>
    <PhonePairing onAdded={onPhoneAdded}/>
    <div className="pair-divider">или сканирай директно с компютъра</div>
    <PairQrScanner onRead={(c,t)=>{setCode(c);setToken(t);void resolve(c,t)}}/>
    <div className="pair-divider">или въведи регистрационните данни</div>
    <form className="modal-form" onSubmit={submit}><label>Сериен номер<input required minLength={3} maxLength={40} value={code} onChange={e=>{setCode(e.target.value.toUpperCase());setResolved(null)}} placeholder="Напр. ST-M6-1001"/></label><label>Еднократен код за сдвояване<input required minLength={12} maxLength={200} value={token} onChange={e=>{setToken(e.target.value);setResolved(null)}} placeholder="Код от устройството или QR етикета"/></label>
      <button type="button" className="btn btn-outline full" disabled={busy||!code||!token} onClick={()=>resolve()}><ScanLine size={16}/> {busy?'Проверка…':'Разпознай модела'}</button>
      {resolved&&<div className="paired-model"><CheckCircle2 size={21}/><div><strong>{resolved.model.name}</strong><small>{resolved.code} · {resolved.model.panel_count} панела · {resolved.kind==='municipal'?'Общинско':'Частно'} дърво</small></div></div>}
      {resolved&&<><label>Име на дървото<input required minLength={2} maxLength={120} value={name} onChange={e=>setName(e.target.value)} placeholder="Напр. Соларно дърво у дома"/></label><label>Местоположение<input required minLength={3} value={location} onChange={e=>setLocation(e.target.value)} placeholder="Град или обект"/></label></>}
      {error&&<ErrorText message={error}/>}
      <div className="modal-actions"><button className="btn btn-quiet" type="button" onClick={onClose}>Отказ</button><button className="btn btn-primary" disabled={busy||!resolved} type="submit">{busy?'Добавяне…':'Добави устройство'}<ArrowRight size={16}/></button></div>
    </form></div></div>
}

function ServiceActionModal({item,mode,onClose,onSave}:{item:Service;mode:'complete'|'schedule';onClose:()=>void;onSave:(days:number)=>Promise<void>}){
  const [days,setDays]=useState(item.interval_days),[busy,setBusy]=useState(false),[error,setError]=useState('')
  async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{await onSave(days)}catch(err){setError((err as Error).message)}finally{setBusy(false)}}
  return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className="modal"><div className="modal-heading"><div><span className="eyebrow">СЕРВИЗЕН ЦЕНТЪР</span><h2>{mode==='complete'?'Потвърждение за обслужване':'Сервизен интервал'}</h2></div><IconButton icon={X} title="Затвори" onClick={onClose}/></div><p><strong>{item.label}</strong> · {item.tree_name}</p><form className="modal-form" onSubmit={submit}>{mode==='schedule'?<><label>Интервал между обслужванията (дни)<input required type="number" min={1} max={3650} value={days} onChange={e=>setDays(Number(e.target.value))}/></label><div className="calendar-note"><Info size={16}/> Интервалът трябва да съответства на сервизната документация на действителното оборудване.</div></>:<div className="calendar-note"><CheckCircle2 size={18}/> Потвърждавам, че компонентът действително е обслужен. Системата ще запише днешната дата и ще изчисли следващия срок.</div>}{error&&<ErrorText message={error}/>}<div className="modal-actions"><button className="btn btn-quiet" type="button" onClick={onClose}>Отказ</button><button className="btn btn-primary" type="submit" disabled={busy}>{busy?'Запис…':mode==='schedule'?'Запази интервала':'Потвърди обслужването'}<Check size={16}/></button></div></form></div></div>
}
function ProfilePage({user,onSave,onPassword,onLogout}:{user:User;onSave:(name:string)=>Promise<void>;onPassword:(oldPassword:string,newPassword:string)=>Promise<void>;onLogout:()=>void}){
  const [name,setName]=useState(user.name),[current,setCurrent]=useState(''),[next,setNext]=useState(''),[busy,setBusy]=useState(false),[notice,setNotice]=useState(''),[error,setError]=useState('')
  useEffect(()=>{setName(user.name)},[user.name])
  async function changeName(e:FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await onSave(name);setNotice('Промените са запазени.')}catch(x){setError((x as Error).message)}finally{setBusy(false)}}
  async function changePassword(e:FormEvent){e.preventDefault();setBusy(true);setError('');setNotice('');try{await onPassword(current,next);setCurrent('');setNext('');setNotice('Паролата е променена успешно.')}catch(x){setError((x as Error).message)}finally{setBusy(false)}}
  return <div className="page-body profile-page"><SectionHeading eyebrow="МОЯТ АКАУНТ" title="Личен профил"/><div className="profile-header-card"><span className="profile-big-avatar">{initial(user.name)}</span><div><h2>{user.name}</h2><p>{user.email}</p><span className="profile-access-tag"><ShieldCheck size={14}/>{user.role==='municipality'?'Общински служител':'Частен собственик'}</span></div></div><div className="profile-grid"><Panel className="profile-box"><div className="profile-box-title"><UserRound size={19}/><h3>Лични данни</h3></div><form onSubmit={changeName} className="modal-form"><label>Име и фамилия<input value={name} onChange={e=>setName(e.target.value)} minLength={2} maxLength={100} required/></label><label>Имейл адрес<input value={user.email} disabled type="email"/></label><small className="profile-hint">Имейлът и ролята се управляват от системата.</small><button className="btn btn-primary" disabled={busy||name.trim()===user.name} type="submit">Запази промените <Check size={16}/></button></form></Panel><Panel className="profile-box"><div className="profile-box-title"><LockKeyhole size={19}/><h3>Сигурност</h3></div><form onSubmit={changePassword} className="modal-form"><label>Настояща парола<input type="password" autoComplete="current-password" value={current} onChange={e=>setCurrent(e.target.value)} required/></label><label>Нова парола<input type="password" autoComplete="new-password" minLength={8} required value={next} onChange={e=>setNext(e.target.value)}/></label><button type="submit" className="btn btn-outline" disabled={busy||!current||next.length<8}>Промени паролата</button></form></Panel></div>{error&&<ErrorText message={error}/>} {notice&&<div className="profile-success"><CheckCircle2 size={17}/>{notice}</div>}<button className="profile-logout" onClick={onLogout}><LogOut size={17}/> Излез от профила</button></div>
}
const navItems:{key:Page;icon:LucideIcon;label:string}[]=[{key:'overview',icon:Gauge,label:'Преглед'},{key:'trees',icon:TreePine,label:'Моите дървета'},{key:'insights',icon:Activity,label:'Анализи'},{key:'assistant',icon:MessageCircle,label:'AI асистент'},{key:'service',icon:Wrench,label:'Сервиз'}]
const pageNames:Record<Page,string>={overview:'Преглед',trees:'Моите дървета',detail:'Детайли',insights:'Анализи',assistant:'AI асистент',service:'Сервиз',settings:'Настройки',profile:'Профил'}

export default function App(){
  const [user,setUser]=useState<User|null>(null),[ready,setReady]=useState(false),[trees,setTrees]=useState<Tree[]>([]),[alerts,setAlerts]=useState<Alert[]>([]),[services,setServices]=useState<Service[]>([]),[health,setHealth]=useState<Health|null>(null)
  const [page,setPage]=useState<Page>('overview'),[selectedId,setSelectedId]=useState<number|null>(null),[readings,setReadings]=useState<Reading[]>([]),[forecast,setForecast]=useState<Forecast|null>(null),[oxygen,setOxygen]=useState<OxygenHistory|null>(null)
  const [modal,setModal]=useState(false),[connectGuide,setConnectGuide]=useState(false),[notifOpen,setNotifOpen]=useState(false),[search,setSearch]=useState(''),[toast,setToast]=useState(''),[refreshIndex,setRefreshIndex]=useState(0),[busyAction,setBusyAction]=useState(false),[serviceAction,setServiceAction]=useState<{item:Service;mode:'complete'|'schedule'}|null>(null)
  const [theme,setTheme]=useState<'dark'|'light'>(()=>localStorage.getItem('solartree_theme')==='dark'?'dark':'light')
  useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem('solartree_theme',theme)},[theme])
  const selected=trees.find(t=>t.id===selectedId)||trees[0]||null
  const message=(msg:string)=>{setToast(msg);window.setTimeout(()=>setToast(''),4200)}
  const refreshVersion=useRef(0)
  const refresh=useCallback(async()=>{
    const version=++refreshVersion.current
    const [ts,as,ss,h]=await Promise.all([api.trees(),api.alerts(),api.maintenance(),api.health()])
    if(version!==refreshVersion.current)return
    setTrees(ts);setAlerts(as);setServices(ss);setHealth(h)
    setSelectedId(prev=>prev&&ts.some(t=>t.id===prev)?prev:ts[0]?.id??null)
    setRefreshIndex(x=>x+1)
  },[])
  useEffect(()=>{api.me().then(me=>{setUser(me)}).catch(()=>{setAuthToken('')}).finally(()=>setReady(true))},[])
  useEffect(()=>{if(user)refresh().catch(err=>message((err as Error).message))},[user,refresh])
  useEffect(()=>{if(!user)return;const timer=window.setInterval(()=>refresh().catch(()=>{}),60000);return()=>window.clearInterval(timer)},[user,refresh])
  useEffect(()=>{setReadings([]);setForecast(null);setOxygen(null)},[selectedId])
  useEffect(()=>{
    let active=true
    if(!selectedId){setReadings([]);setForecast(null);setOxygen(null);return}
    Promise.all([api.readings(selectedId),api.forecast(selectedId),api.oxygen(selectedId)])
      .then(([r,f,o])=>{if(active){setReadings(r);setForecast(f);setOxygen(o)}})
      .catch(()=>{if(active){setReadings([]);setForecast(null);setOxygen(null)}})
    return ()=>{active=false}
  },[selectedId,refreshIndex])
  const pendingAlerts=alerts.filter(a=>!a.acknowledged)
  const pendingService=services.filter(s=>s.status!=='ok')
  const attention=pendingAlerts.length+pendingService.length
  const totalPower=trees.reduce((sum,t)=>sum+(t.latest_sensors?.power_w??t.latest?.power_w??0),0)
  const waterLevels=trees.map(t=>t.latest_sensors?.water_pct??t.latest?.water_pct).filter((v):v is number=>v!=null)
  const avgWater=waterLevels.length?waterLevels.reduce((sum,v)=>sum+v,0)/waterLevels.length:null
  const includesSimulation=trees.some(t=>t.latest?.source==='simulation')
  const detailsService=services.filter(s=>s.tree_id===selected?.id)
  const filtered=trees.filter(t=>`${t.name} ${t.code} ${t.location}`.toLowerCase().includes(search.toLowerCase()))
  async function removeTree(tree:Tree){
    if(!window.confirm(`Да премахна ли „${tree.name}“ (${tree.code}) от твоя профил? Кодът остава запазен за този акаунт.`))return
    setBusyAction(true)
    try{
      await api.removeTree(tree.id)
      refreshVersion.current++
      setTrees(items=>items.filter(item=>item.id!==tree.id))
      setServices(items=>items.filter(item=>item.tree_id!==tree.id))
      setAlerts(items=>items.filter(item=>item.tree_id!==tree.id))
      setSelectedId(trees.find(item=>item.id!==tree.id)?.id??null)
      setPage('trees')
      message('Дървото е премахнато.')
    }catch(err){message((err as Error).message)}
    finally{setBusyAction(false)}
  }
  const openTree=(id:number)=>{setSelectedId(id);setPage('detail')}
  const onAuth=(payload:TokenPayload)=>{setAuthToken(payload.access_token);setUser(payload.user);setPage('overview')}
  const logout=()=>{refreshVersion.current++;setAuthToken('');setUser(null);setTrees([]);setSelectedId(null);setPage('overview');setNotifOpen(false)}
  const action=async(run:()=>Promise<unknown>,success:string)=>{setBusyAction(true);try{await run();await refresh();message(success)}catch(err){message((err as Error).message)}finally{setBusyAction(false)}}
  const saveServiceAction=async(days:number)=>{if(!serviceAction)return;const {item,mode}=serviceAction;if(mode==='schedule')await api.serviceSchedule(item.tree_id,item.component,days);else await api.serviceDone(item.tree_id,item.component);await refresh();setServiceAction(null);message(mode==='schedule'?'Сервизният интервал е обновен.':'Обслужването е записано.')}
  const create=async(value:{name:string;code:string;claim_token:string;location:string;lat:number|null;lng:number|null})=>{const tree=await api.createTree(value);await refresh();setSelectedId(tree.id);setPage('detail');setModal(false);message('Дървото е добавено.')}
  const phoneAdded=useCallback(async(treeId:number)=>{await refresh();setSelectedId(treeId);setPage('detail');setModal(false);message('Устройството е добавено чрез телефона.')},[refresh])
  const nav=(p:Page)=>{setPage(p);setNotifOpen(false)}
  const saveProfile=async(name:string)=>{const updated=await api.updateProfile(name);setUser(updated)}
  const changePassword=async(current:string,next:string)=>{await api.changePassword(current,next)}
  if(!ready)return <div className="boot"><div className="boot-logo"><Leaf size={32}/></div><span>SolarTree AI</span></div>
  if(!user)return <AuthScreen onSuccess={onAuth}/>
  return <div className="app-shell">
    <aside className="sidebar"><div className="side-brand"><Logo/></div>
      <div className="sidebar-workspace"><span className="workspace-dot"/><strong>{user.role==='municipality'?'Общинска мрежа':'Моето пространство'}</strong></div>
      <nav className="side-nav" aria-label="Основна навигация">{navItems.map(({key,icon:Icon,label})=><button key={key} title={label} className={page===key||(page==='detail'&&key==='trees')?'selected':''} onClick={()=>nav(key)}><Icon size={19}/><span>{key==='trees'&&user.role==='municipality'?'Общински дървета':label}</span>{key==='service'&&attention>0&&<i className="side-count">{attention}</i>}</button>)}</nav>
      <div className="sidebar-spacer"/>
      <div className="side-nav side-bottom"><button className={page==='settings'?'selected':''} onClick={()=>nav('settings')}><Settings2 size={19}/><span>Настройки</span></button></div>
      <div className="side-profile"><button className="profile-launch" title="Отвори профила" onClick={()=>nav('profile')}><span className="avatar">{initial(user.name)}</span><span className="side-profile-name"><strong>{user.name}</strong><span>{user.role==='municipality'?'Общински администратор':'Частен собственик'}</span></span></button><button title="Изход" onClick={logout}><LogOut size={17}/></button></div>
    </aside>
    <main className="main-area"><header className="topbar"><div className="top-heading"><span className="breadcrumb">SolarTree <ChevronRight size={13}/> {page==='detail'?'Дървета':pageNames[page]}</span><h1>{page==='detail'?selected?.name||'Дърво':pageNames[page]}</h1></div><div className="top-actions"><button className="theme-switch" type="button" onClick={()=>setTheme(v=>v==='dark'?'light':'dark')} aria-label={theme==='dark'?'Светла тема':'Тъмна тема'} title={theme==='dark'?'Светла тема':'Тъмна тема'}>{theme==='dark'?<Sun size={17}/>:<Moon size={17}/>}<span>{theme==='dark'?'Светла':'Тъмна'}</span></button><div className="system-state"><span className="pulse-dot"/> Сървърът е активен</div><IconButton icon={RefreshCw} title="Обнови данните" onClick={()=>refresh().catch(e=>message((e as Error).message))}/><div className="notifications-wrap"><IconButton icon={Bell} title="Известия" badge={attention>0} active={notifOpen} onClick={()=>setNotifOpen(v=>!v)}/>{notifOpen&&<div className="notification-pop"><div className="popover-head"><strong>Известия</strong><span>{attention} активни</span></div>{attention===0?<div className="notification-empty"><CheckCircle2 size={20}/> Няма нови известия</div>:<div className="notif-list">{pendingService.slice(0,4).map(s=><button key={`s${s.id}`} onClick={()=>{setSelectedId(s.tree_id);nav('service')}}><span className="notif-icon amber"><Wrench size={17}/></span><span><strong>{s.label}</strong><small>{s.tree_name} · {relativeDay(s)}</small></span><ChevronRight size={15}/></button>)}{pendingAlerts.slice(0,4).map(a=><button key={`a${a.id}`} onClick={()=>{setSelectedId(a.tree_id);nav('service')}}><span className="notif-icon danger"><CircleAlert size={17}/></span><span><strong>Необичайни показания</strong><small>{a.tree_name}</small></span><ChevronRight size={15}/></button>)}</div>}<button className="popover-footer" onClick={()=>nav('service')}>Отвори сервизния център <ArrowRight size={14}/></button></div>}</div><button type="button" title="Отвори моя профил" aria-label="Отвори моя профил" className="top-avatar profile-avatar-button" onClick={()=>nav('profile')}>{initial(user.name)}</button></div></header>
    <div className="main-scroll">
    {page==='overview'&&<div className="page-body dashboard"><div className="welcome-row"><div><span className="eyebrow"><span className="accent-tick"/> {user.role==='municipality'?'УПРАВЛЕНИЕ НА МРЕЖАТА':'ЛИЧЕН ЕНЕРГИЕН ЦЕНТЪР'}</span><h2>Добре дошъл, {user.name.split(' ')[0]}<span className="welcome-dot">.</span></h2><p>Твоите устройства, енергия и поддръжка — в един поглед.</p></div><button className="btn btn-outline" onClick={()=>setModal(true)}><Plus size={17}/> Добави дърво</button></div>
      <div className="stat-grid"><StatCard icon={TreePine} label="Соларни дървета" value={String(trees.length).padStart(2,'0')} sub={user.role==='municipality'?'В общинската мрежа':'В личния ти профил'} accent="green"/><StatCard icon={Zap} label="Соларна мощност" value={`${formatNum(totalPower/1000,2)} kW`} sub={includesSimulation?'Включва симулирана мощност':'Общо от последните записи'} accent="blue"/><StatCard icon={Droplets} label="Ниво на резервоарите" value={avgWater===null?'—':`${formatNum(avgWater)}%`} sub={includesSimulation?'Включва симулирано ниво':'Средно от наличните нива'} accent="purple"/><StatCard icon={Bell} label="За внимание" value={String(attention).padStart(2,'0')} sub="Сервизни задачи и сигнали" accent="orange"/></div>
      {trees.length>0&&<div className="context-selector">
        <label htmlFor="overview-tree">Избрано устройство</label>
        <select id="overview-tree" value={selected?.id??''} onChange={e=>setSelectedId(Number(e.target.value))}>
          {trees.map(tree=><option key={tree.id} value={tree.id}>{tree.name} · {tree.code}</option>)}
        </select>
      </div>}
      <div className="dashboard-main"><Panel className="featured-panel"><div className="featured-top"><div><span className="eyebrow">ИЗБРАНО УСТРОЙСТВО</span><h3>{selected?.name||'Няма избрано дърво'}</h3><span className="device-subtitle">{selected?.code||'—'} {selected?' · '+selected.location:''}</span></div>{selected&&<StatePill tree={selected}/>}</div><DeviceMedia tree={selected} compact onChanged={refresh}/><div className="featured-bottom"><div className="featured-reading"><span>МОЩНОСТ</span><strong>{selected?.latest_sensors?.power_w!=null?`${formatNum(selected.latest_sensors.power_w)} W`:selected?.latest?`${formatNum(selected.latest.power_w)} W`:'—'}</strong></div><div className="featured-reading"><span>КИСЛОРОД</span><strong>{selected?.latest?.oxygen_flow_lph!=null?`${formatNum(selected.latest.oxygen_flow_lph,1)} L/h`:'—'}</strong></div><div className="featured-reading"><span>ВОДЕН РЕЗЕРВОАР</span><strong>{selected?.latest?`${formatNum(selected.latest.water_pct)}%`:'—'}</strong></div><button className="featured-open" disabled={!selected} onClick={()=>selected&&openTree(selected.id)}><ArrowUpRight size={19}/></button></div></Panel><div className="right-stack"><Panel className="trend-panel"><div className="panel-top"><div><span className="eyebrow">МОНИТОРИНГ</span><h3>Производителност</h3></div><span className="chart-unit">W / история</span></div><TelemetryChart readings={readings} small/></Panel><Panel className="attention-panel"><div className="panel-top"><div><span className="eyebrow">СЕРВИЗНИ СЪБИТИЯ</span><h3>Изисква внимание</h3></div><button className="text-link" onClick={()=>nav('service')}>Всички <ArrowRight size={15}/></button></div>{attention===0?<div className="all-clear"><CheckCircle2 size={19}/> Всички устройства са без активни сигнали</div>:<div className="attention-list">{pendingService.slice(0,2).map(s=><button key={s.id} onClick={()=>{setSelectedId(s.tree_id);nav('service')}}><span className="attention-icon"><Wrench size={17}/></span><span><strong>{s.component==='water_filter'?'Смяна на филтър':'Изсушаващ модул'}</strong><small>{s.tree_name} · {relativeDay(s)}</small></span><ChevronRight size={15}/></button>)}{pendingAlerts.slice(0,1).map(a=><button key={a.id} onClick={()=>nav('service')}><span className="attention-icon"><CircleAlert size={17}/></span><span><strong>Необичайни показания</strong><small>{a.tree_name}</small></span><ChevronRight size={15}/></button>)}</div>}</Panel></div></div>
      <Panel className="devices-panel"><div className="panel-top"><div><span className="eyebrow">УСТРОЙСТВА</span><h3>{user.role==='municipality'?'Общинска мрежа':'Моите соларни дървета'}</h3></div><button className="text-link" onClick={()=>nav('trees')}>Виж всички <ArrowRight size={16}/></button></div>{!trees.length?<Empty title="Добави първото си дърво" desc="Регистрирай устройство, за да започнеш мониторинг." action={<button className="btn btn-primary" onClick={()=>setModal(true)}><Plus size={16}/> Добави дърво</button>}/>:<div className="devices-rows">{trees.slice(0,4).map(t=><button className="device-row" key={t.id} onClick={()=>openTree(t.id)}><span className="tree-icon"><SolarTreeMark size={27}/></span><span className="device-row-main"><strong>{t.name}</strong><small>{t.code} · {t.location}</small></span><span className="device-row-power">{t.latest?`${formatNum(t.latest.power_w)} W`:'—'}</span><StatePill tree={t}/><ChevronRight className="row-chevron" size={18}/></button>)}</div>}</Panel>
    </div>}
    {page==='trees'&&<div className="page-body"><SectionHeading eyebrow="ТВОЯТА МРЕЖА" title={user.role==='municipality'?'Общински соларни дървета':'Моите соларни дървета'} action={<div className="tree-header-actions"><button className="btn btn-primary" onClick={()=>setModal(true)}><Plus size={17}/> Ново дърво</button></div>}/><div className="filter-line"><div className="search-box"><Search size={18}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Търси по име, код или местоположение"/></div><div className="list-count"><SlidersHorizontal size={16}/> {filtered.length} устройства</div></div>{!filtered.length?<Panel><Empty icon={TreePine} title={trees.length?'Няма резултати':'Все още няма дървета'} desc={trees.length?'Промени търсенето.':'Добави първото си устройство, за да започнеш.'} action={<button className="btn btn-outline" onClick={()=>{setSearch('');if(!trees.length)setModal(true)}}>{trees.length?'Изчисти търсенето':'Добави дърво'}</button>}/></Panel>:<div className="tree-grid">{filtered.map(t=><button className="tree-card" key={t.id} onClick={()=>openTree(t.id)}><div className="tree-card-upper"><span className="tree-card-icon"><SolarTreeMark size={30}/></span><StatePill tree={t}/></div><DeviceThumbnail tree={t}/><div className="tree-card-name"><span>{t.code}</span><h3>{t.name}</h3><p><MapPin size={13}/>{t.location}</p></div><div className="tree-card-bottom"><span><small>Мощност</small><strong>{t.latest?`${formatNum(t.latest.power_w)} W`:'—'}</strong></span><span><small>{t.model.code==='ST-URBAN-2KW'?'Вода / H₂ съд':'Резервоар'}</small><strong>{t.model.code==='ST-URBAN-2KW'?'10 L / 20 L':t.latest?`${formatNum(t.latest.water_pct)}%`:'—'}</strong></span><span className="tree-card-arrow"><ArrowUpRight size={20}/></span></div></button>)}</div>}</div>}
    {page==='detail'&&<div className="page-body detail-page">{!selected?<Empty title="Няма избрано дърво" desc="Добави или избери устройство от списъка."/>:<><div className="detail-actions"><button className="back-link" onClick={()=>nav('trees')}><ArrowLeft size={16}/> Всички дървета</button><div className="detail-actions-right"><StatePill tree={selected}/><button type="button" disabled={busyAction} className="btn btn-subtle-warning" onClick={()=>removeTree(selected)}>Премахни дървото</button>{!selected.simulation&&<button className="btn btn-outline" onClick={()=>setConnectGuide(true)}><Wifi size={16}/> Свържи устройство</button>}<button className="btn btn-outline" onClick={()=>nav('assistant')}><Sparkles size={16}/> Попитай AI</button></div></div><div className="detail-grid"><Panel className="model-panel"><div className="model-panel-top"><div><span className="eyebrow">СНИМКА ИЛИ ВИДЕО</span><h3>{selected.name}</h3><span className="muted-small">{selected.code} · {selected.model.panel_count} панела · Каталожна конфигурация</span></div><span className="outline-badge model-identified"><CheckCircle2 size={13}/> {selected.model.name}</span></div>{selected.model.electrolyzer_kw&&<div className="industrial-specs"><span>Електролизер <strong>{selected.model.electrolyzer_kw} kW</strong></span><span>O₂ (проектно) <strong>{selected.model.oxygen_nominal_lph} L/h</strong></span><span>Горивна клетка <strong>{selected.model.fuel_cell_kw} kW</strong></span>{selected.model.water_tank_l&&<span>Вода <strong>{selected.model.water_tank_l} L</strong></span>}{selected.model.hydrogen_tank_l&&<span>H₂ съд <strong>{selected.model.hydrogen_tank_l} L</strong></span>}</div>}<DeviceMedia tree={selected}/></Panel><div className="detail-side"><Panel className="detail-status"><span className="eyebrow">ТЕКУЩИ ДАННИ</span><div className="detail-power"><Zap size={24}/><strong>{selected.latest?formatNum(selected.latest.power_w):'—'}</strong><span>W</span></div><span className="muted-small">Последно обновяване: {selected.latest?`${formatWhen(selected.latest.time)}, ${formatTime(selected.latest.time)}`:'няма записи'}</span><div className="detail-separator"/><div className="telemetry-mini"><div><Sun size={17}/><span>Температура</span><strong>{selected.latest_sensors?.temperature_c!=null?`${formatNum(selected.latest_sensors.temperature_c,1)}°C`:selected.latest?`${formatNum(selected.latest.temperature_c,1)}°C`:'—'}</strong></div><div><Droplets size={17}/><span>Влажност</span><strong>{selected.latest_sensors?.humidity_pct!=null?`${formatNum(selected.latest_sensors.humidity_pct,1)}%`:selected.latest?`${formatNum(selected.latest.humidity_pct,1)}%`:'—'}</strong></div><div><Waves size={17}/><span>Ниво на водата</span><strong>{selected.latest_sensors?.water_pct!=null?`${formatNum(selected.latest_sensors.water_pct,1)}%`:selected.latest?`${formatNum(selected.latest.water_pct,1)}%`:'—'}</strong></div><div><Activity size={17}/><span>{selected.simulation||selected.latest_sensors?.mq8_adc_raw!=null?'MQ-8 (суров ADC)':'MQ-8 (отн. единици)'}</span><strong>{selected.simulation ? formatNum(selected.simulation.mq8_adc_raw) : selected.latest_sensors?.mq8_adc_raw!=null?selected.latest_sensors.mq8_adc_raw:selected.latest?formatNum(selected.latest.h2_sensor_value,2):'—'}</strong></div></div></Panel><Panel className="detail-service"><div className="panel-top"><div><span className="eyebrow">ПОДДРЪЖКА</span><h3>Сервизно състояние</h3></div><Wrench size={19}/></div>{detailsService.map(s=><div className="detail-service-row" key={s.id}><span className={`service-indicator ${serviceColor(s.status)}`}/><div><strong>{s.component==='water_filter'?'Воден филтър':'Изсушаващ модул'}</strong><small>{s.status==='ok'?'Следваща смяна: ': 'Срок: '}{formatWhen(s.due_at)}</small></div><span className={s.status==='ok'?'ok-text':'warn-text'}>{relativeDay(s)}</span></div>)}<button className="text-link" onClick={()=>nav('service')}>Сервизни детайли <ArrowRight size={15}/></button></Panel></div></div><div className="detail-bottom"><Panel className="detail-history"><div className="panel-top"><div><span className="eyebrow">ИСТОРИЯ</span><h3>Енергийна активност</h3></div><span className="chart-unit">W / 15 мин.</span></div><TelemetryChart readings={readings}/></Panel>{selected.simulation ? <Panel className="scenarios-panel">
      <span className="eyebrow">АВТОМАТИЧНА СИМУЛАЦИЯ</span><h3>Работа на Urban 2K</h3>
      <p>Стойностите се обновяват всяка минута. Панелите захранват електролизера през деня. Горивната клетка черпи от запаса на водород и през нощта.</p>
      <div className="model-metric"><span>Електролизер</span><strong>{formatNum(selected.latest?.electrolyzer_power_w??0)} W</strong></div>
      <div className="model-metric"><span>Производство на H₂</span><strong>{formatNum(selected.simulation.hydrogen_flow_nlph,1)} Nl/h</strong></div>
      <div className="model-metric"><span>Горивна клетка</span><strong>{formatNum(selected.simulation.fuel_cell_load_kw*1000)} W</strong></div>
      <div className="model-metric"><span>Налягане в съда</span><strong>{formatNum(selected.simulation.hydrogen_pressure_bar_g,1)} bar(g)</strong></div>
    </Panel> : <Panel className="scenarios-panel"><span className="eyebrow">АНАЛИЗ И ТЕСТОВЕ</span><h3>Сценарии и анализ</h3><p>Изследвай различни състояния, без да изпращаш команди към физическото устройство.</p><div className="scenario-callout"><Info size={17}/> Сценариите записват само виртуални измервания.</div><button disabled={busyAction||!health?.simulation_enabled} className="btn btn-outline full" onClick={()=>action(()=>api.simulate(selected.id,'normal'),'Добавено е виртуално измерване.')}><Activity size={16}/> Нормален сценарий</button><button disabled={busyAction||!health?.simulation_enabled} className="btn btn-subtle-warning full" onClick={()=>action(()=>api.simulate(selected.id,'anomaly'),'Генериран е сценарий с отклонение.')}><CircleAlert size={16}/> Сценарий с отклонение</button><span className="source-indicator">Източник на последния запис: {selected.latest?.source==='device'?'устройство':selected.latest?.source==='simulation'?'виртуален модел':'няма'}</span></Panel>}</div>{selected.model.code==='ST-URBAN-2KW'&&<ResourcePlanner key={selected.id} tree={selected}/>}<Panel className="oxygen-detail-panel"><div className="panel-top"><div><span className="eyebrow">КИСЛОРОД</span><h3>Произведен кислород</h3></div><span className="chart-unit">L · за наличния период</span></div><OxygenChart history={oxygen}/><p className="oxygen-footnote">{oxygen?.note||'Данните ще се появят след свързване на измерването.'}</p></Panel></>}</div>}
    {page==='insights'&&<div className="page-body"><SectionHeading eyebrow="INTELLIGENCE ENGINE" title="Анализи и прогнози"/><div className="context-selector"><span><TreePine size={17}/> Избрано устройство</span><select value={selected?.id??''} onChange={e=>setSelectedId(Number(e.target.value))}>{trees.map(t=><option key={t.id} value={t.id}>{t.name} · {t.code}</option>)}</select></div><div className="insight-banner"><div><span className="eyebrow">ПРОГНОЗЕН МОДЕЛ</span><h3>От данните към решенията.</h3><p>Моделът анализира историята на измерванията и изчислява ориентировъчната електрическа мощност за следващите интервали.</p></div><div className="insight-visual"><BrainCircuit size={82} strokeWidth={1.1}/></div></div><div className="insight-grid"><Panel><div className="panel-top"><div><span className="eyebrow">МАШИННО ОБУЧЕНИЕ</span><h3>Прогноза за мощност</h3></div><span className="outline-badge">6 интервала</span></div><ForecastChart forecast={forecast}/></Panel><Panel className="insight-model-info"><span className="eyebrow">МОДЕЛ И ТОЧНОСТ</span><h3>{forecast?.model||'Няма данни'}</h3><div className="model-metric"><span>Обучаващи записи</span><strong>{forecast?.trained_samples??'—'}</strong></div><div className="model-metric"><span>Средна абсолютна грешка (MAE)</span><strong>{forecast?.mae_w==null?'—':`${formatNum(forecast.mae_w,1)} W`}</strong></div><div className="model-metric"><span>Източник на данните</span><strong>{selected?.latest?.source==='device'?'Устройство':selected?.latest?.source==='simulation'?'Виртуален модел':'Няма данни'}</strong></div><div className="info-box"><Info size={16}/> Прогнозата е експериментален анализ, не измерване и не команда за управление.</div></Panel></div><Panel className="oxygen-insight-panel"><div className="panel-top"><div><span className="eyebrow">O₂ ANALYTICS</span><h3>Производство на кислород</h3></div><Waves size={21}/></div><OxygenChart history={oxygen}/></Panel><Panel className="insight-bottom"><div className="insight-icon"><ShieldCheck size={24}/></div><div><h3>Откриване на необичайни показания</h3><p>Модулът сравнява новите измервания с историческите данни. При значимо отклонение се създава известие за проверка. Аварийните защити на реалното устройство са независими.</p></div><button className="btn btn-outline" onClick={()=>nav('service')}>Виж събитията <ArrowRight size={15}/></button></Panel></div>}
    {page==='assistant'&&<AssistantPage key={user.id+'-'+trees.map(t=>t.id).join(',')} health={health} trees={trees} selected={selected} onSelect={setSelectedId}/>}
    {page==='service'&&<div className="page-body"><SectionHeading eyebrow="SERVICE CENTER" title="Поддръжка и известия"/><div className="service-summary"><div className="service-kpi"><div className="service-kpi-icon"><Wrench size={20}/></div><div><span>За обслужване</span><strong>{pendingService.length}</strong></div></div><div className="service-kpi"><div className="service-kpi-icon amber"><Clock3 size={20}/></div><div><span>Предстоящи смени</span><strong>{services.filter(s=>s.status==='soon').length}</strong></div></div><div className="service-kpi"><div className="service-kpi-icon red"><Bell size={20}/></div><div><span>Активни сигнали</span><strong>{pendingAlerts.length}</strong></div></div></div><div className="service-sections"><Panel><div className="panel-top"><div><span className="eyebrow">ПРЕВАНТИВНА ПОДДРЪЖКА</span><h3>Сервизен график</h3></div><span className="chart-unit">Изчислено по календар</span></div>{!services.length?<Empty icon={Wrench} title="Няма сервизни записи" desc="При добавяне на устройство ще се създаде сервизен график."/>:<div className="service-list">{[...services].sort((a,b)=>a.days_left-b.days_left).map(s=><div className="service-item" key={s.id}><span className={`service-item-icon ${serviceColor(s.status)}`}>{s.component==='water_filter'?<Filter size={20}/>:<Droplets size={20}/>}</span><div className="service-item-info"><strong>{s.label}</strong><small>{s.tree_name} · {formatWhen(s.due_at)}</small><span className={`service-state ${serviceColor(s.status)}`}>{s.status==='overdue'?'Просрочен':s.status==='soon'?'Предстои':'По график'} · {relativeDay(s)}</span></div><div className="service-item-actions"><button className="icon-btn" title="Промени сервизен интервал" disabled={busyAction} onClick={()=>setServiceAction({item:s,mode:'schedule'})}><Settings2 size={15}/></button><button className="btn btn-outline btn-small" disabled={busyAction} onClick={()=>setServiceAction({item:s,mode:'complete'})}><Check size={15}/> Обслужено</button></div></div>)}</div>}<div className="calendar-note"><Info size={16}/> Сроковете са приблизителни и се основават на зададени интервали, а не на измерено износване. Коригирай ги според спецификацията на производителя.</div></Panel><Panel className="alerts-panel"><div className="panel-top"><div><span className="eyebrow">СЪБИТИЯ</span><h3>Сигнали и история</h3></div><span className="outline-badge">{alerts.length}</span></div>{!alerts.length?<div className="all-clear large"><CheckCircle2 size={24}/> Няма регистрирани отклонения</div>:<div className="alerts-list">{alerts.map(a=><div className="alert-item" key={a.id}><span className={`alert-glyph ${a.acknowledged?'resolved':''}`}><CircleAlert size={19}/></span><div><strong>{a.message}</strong><small>{a.tree_name} · {formatWhen(a.time)} · {formatTime(a.time)}</small></div>{a.acknowledged?<span className="tag-done"><Check size={13}/> Разгледан</span>:<button className="btn btn-outline btn-small" disabled={busyAction} onClick={()=>action(()=>api.ack(a.id),'Сигналът е отбелязан като разгледан.')}>Разгледано</button>}</div>)}</div>}</Panel></div></div>}
    {page==='profile'&&<ProfilePage user={user} onSave={saveProfile} onPassword={changePassword} onLogout={logout}/>}
    {page==='settings'&&<div className="page-body"><SectionHeading eyebrow="PREFERENCES & INTEGRATIONS" title="Настройки"/><div className="settings-grid"><Panel className="settings-block"><div className="settings-icon"><UserRound size={22}/></div><h3>Профил и достъп</h3><p>Идентичност и права за текущото работно пространство.</p><button className="btn btn-outline" onClick={()=>nav('profile')}>Редактирай профила <ArrowRight size={15}/></button><div className="setting-line"><span>Потребител</span><strong>{user.name}</strong></div><div className="setting-line"><span>Имейл</span><strong>{user.email}</strong></div><div className="setting-line"><span>Роля</span><strong>{user.role==='municipality'?'Общински служител':'Собственик'}</strong></div></Panel><Panel className="settings-block"><div className="settings-icon"><BrainCircuit size={22}/></div><h3>AI интеграция</h3><p>Свободен разговор чрез езиков модел. API ключът се съхранява само на сървъра.</p><div className="setting-line"><span>Състояние</span><span className={`integration-state ${health?.real_llm?'connected':'disconnected'}`}><i/>{health?.real_llm?'Свързано':'Не е конфигурирано'}</span></div><div className="setting-line"><span>Настройка</span><strong>backend/.env</strong></div><button className="btn btn-outline" onClick={()=>nav('assistant')}>Към асистента <ArrowRight size={15}/></button></Panel><Panel className="settings-block"><div className="settings-icon"><Database size={22}/></div><h3>Източници на данни</h3><p>Приложението съхранява измерванията в локалната база данни.</p><div className="setting-line"><span>Свързани устройства</span><strong>{trees.filter(t=>t.connection==='live').length}</strong></div><div className="setting-line"><span>Дървета с тестови данни</span><strong>{trees.filter(t=>t.connection==='model').length}</strong></div><div className="setting-line"><span>Версия</span><strong>{health?.version||'0.5.0'}</strong></div></Panel><Panel className="settings-block"><div className="settings-icon"><Shield size={22}/></div><h3>Управление на безопасността</h3><p>Платформата показва данни и препоръки. Не управлява защитните вериги на електролизера или газовата система.</p><div className="setting-line"><span>Достъп</span><strong>Сървърно ограничен по роли</strong></div><div className="setting-line"><span>Управление на газова система</span><strong>Неактивно</strong></div></Panel></div></div>}
    </div></main>
    <div className="mobile-nav">{navItems.map(({key,icon:Icon,label})=><button key={key} className={page===key||(page==='detail'&&key==='trees')?'active':''} onClick={()=>nav(key)}><Icon size={21}/><span>{key==='trees'?'Дървета':key==='assistant'?'AI':label}</span></button>)}</div>
    {connectGuide&&selected&&<ConnectionGuide tree={selected} onClose={()=>setConnectGuide(false)}/>}
    {serviceAction&&<ServiceActionModal item={serviceAction.item} mode={serviceAction.mode} onClose={()=>setServiceAction(null)} onSave={saveServiceAction}/>}
    {modal&&<NewTreeModal onClose={()=>setModal(false)} onSave={create} onPhoneAdded={phoneAdded}/>}{toast&&<div className="toast"><Info size={17}/>{toast}<button onClick={()=>setToast('')} aria-label="Затвори"><X size={15}/></button></div>}
  </div>
}
function StatCard({icon:Icon,label,value,sub,accent}:{icon:LucideIcon;label:string;value:string;sub:string;accent:string}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon ${accent}`}><Icon size={19}/></span></div><strong>{value}</strong><div className="stat-sub"><span className={`stat-spark ${accent}`}/>{sub}</div></div>}
function AssistantPage({health,trees,selected,onSelect}:{health:Health|null;trees:Tree[];selected:Tree|null;onSelect:(id:number)=>void}){
  const [text,setText]=useState(''),[chat,setChat]=useState<ChatMessage[]>([]),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const [wholeAccount,setWholeAccount]=useState(true)
  const scopeId=wholeAccount?null:selected?.id??null
  const requestNumber=useRef(0)
  const endRef=useRef<HTMLDivElement>(null)
  useEffect(()=>{endRef.current?.scrollIntoView({behavior:'smooth',block:'end'})},[chat,busy])
  useEffect(()=>{setChat([]);setError('');setBusy(false);return ()=>{requestNumber.current++}},[scopeId])
  const send=async(value?:string,report?:'overview'|'energy'|'maintenance')=>{
    const q=(value??text).trim();if(!q||busy||(!report&&!health?.real_llm))return
    const request=++requestNumber.current
    setChat(prev=>[...prev,{role:'user',content:q}]);setText('');setBusy(true);setError('')
    try{const resp=await api.chat(q,scopeId,chat,report);if(request!==requestNumber.current)return;setChat(prev=>[...prev,{role:'assistant',content:resp.reply}])}
    catch(err){if(request===requestNumber.current)setError((err as Error).message)}finally{if(request===requestNumber.current)setBusy(false)}
  }
  return <div className="page-body assistant-page"><div className="assistant-layout"><Panel className="conversation-panel"><div className="chat-head"><div className="chat-identity"><span className="assistant-avatar"><Sparkles size={23}/></span><div><h3>SolarTree Intelligence</h3><small>{health?.real_llm?'Свободен разговор с AI':'Справки от данните в профила'}</small></div></div></div>
    <div className="prompt-chips">{([['overview','Състояние'],['energy','Мощност, вода и кислород'],['maintenance','Сервизни срокове']] as const).map(([kind,label])=><button key={kind} disabled={busy} onClick={()=>send(label,kind)}>{label}</button>)}</div>
    <div className="chat-stream">{chat.length===0?<div className="chat-intro"><div className="chat-intro-icon"><BrainCircuit size={39} strokeWidth={1.4}/></div><span className="eyebrow">SOLARTREE AI</span><h2>Как мога да помогна?</h2><p>{health?.real_llm?'Избери справка или задай въпрос за дърветата в профила си.':'Избери справка по-горе. За свободен разговор администраторът може да добави OPENAI_API_KEY в настройките на сървъра.'}</p></div>:<div className="chat-bubbles">{chat.map((msg,i)=><div key={i} className={`chat-bubble ${msg.role}`}><span className="chat-bubble-avatar">{msg.role==='assistant'?<Sparkles size={15}/>:<UserRound size={15}/>}</span><div style={{whiteSpace:'pre-wrap'}}>{msg.content}</div></div>)}{busy&&<div className="chat-bubble assistant"><span className="chat-bubble-avatar"><Sparkles size={15}/></span><div className="typing"><i/><i/><i/></div></div>}<div ref={endRef}/></div>}</div>{error&&<div className="chat-error"><ErrorText message={error}/></div>}<div className="chat-input-area"><div className="chat-input-box"><textarea aria-label="Съобщение до AI асистента" value={text} disabled={!health?.real_llm||busy} rows={2} placeholder={health?.real_llm?'Напиши съобщение…':'AI ще бъде достъпен след конфигуриране на API ключ'} onChange={e=>setText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}}}/><button type="button" aria-label="Изпрати" disabled={!health?.real_llm||busy||!text.trim()} onClick={()=>send()}><Send size={18}/></button></div><small>AI предоставя информация и препоръки. Не управлява физически защитни системи.</small></div></Panel><div className="assistant-context"><Panel className="context-card"><span className="eyebrow">КОНТЕКСТ НА РАЗГОВОРА</span><h3>Обхват</h3><select aria-label="Обхват на разговора" value={scopeId??''} onChange={e=>{setWholeAccount(!e.target.value);if(e.target.value)onSelect(Number(e.target.value))}}><option value="">Всички мои дървета</option>{trees.map(t=><option value={t.id} key={t.id}>{t.name}</option>)}</select>{wholeAccount?<p>Дървета в профила: {trees.length}</p>:<><div className="context-device"><div className="context-tree-icon"><TreePine size={28}/></div><h4>{selected?.name||'Няма дърво'}</h4><span>{selected?.code||'—'}</span></div><div className="context-metric"><span>Мощност</span><strong>{selected?.latest_sensors?.power_w!=null?`${formatNum(selected.latest_sensors.power_w)} W`:selected?.latest?`${formatNum(selected.latest.power_w)} W`:'—'}</strong></div><div className="context-metric"><span>Вода</span><strong>{selected?.latest?`${formatNum(selected.latest.water_pct)}%`:'—'}</strong></div><div className="context-metric"><span>Източник</span><strong>{selected?.latest?.source==='device'?'Устройство':selected?.connection==='model'?'Симулация':'Няма измерване'}</strong></div></>}</Panel><Panel className="context-privacy"><ShieldCheck size={22}/><h3>Твоите данни остават твои</h3><p>При свободен разговор към AI се изпращат въпросът, историята на разговора и данни за дърветата в твоя профил. Справките се изготвят на сървъра на SolarTree.</p></Panel></div></div></div>
}
